insert into public.countries (iso_code, name_en, name_he, difficulty, continent, capital_en, capital_he, flag_asset, fact_en, fact_he)
values
  ('DZ', 'Algeria', 'אלג׳יריה', 'medium', 'africa', 'Algiers', 'אלג׳יר', 'flags/4x3/dz.svg', 'Algeria is the largest country in Africa by area.', 'אלג׳יריה היא המדינה הגדולה ביותר באפריקה בשטחה.'),
  ('AO', 'Angola', 'אנגולה', 'hard', 'africa', 'Luanda', 'לואנדה', 'flags/4x3/ao.svg', 'The flag shows half a cogwheel and a machete, symbols of industrial workers and peasants.', 'בדגל מופיעים חצי גלגל שיניים ומצ׳טה — סמלים של פועלי התעשייה והאיכרים.'),
  ('BJ', 'Benin', 'בנין', 'hard', 'africa', 'Porto-Novo', 'פורטו נובו', 'flags/4x3/bj.svg', 'Benin''s official capital is Porto-Novo, but the seat of government is Cotonou.', 'הבירה הרשמית של בנין היא פורטו נובו, אך מושב הממשלה נמצא בקוטונו.'),
  ('BW', 'Botswana', 'בוטסואנה', 'hard', 'africa', 'Gaborone', 'גבורונה', 'flags/4x3/bw.svg', 'The light blue on the flag represents water — rain is so valued that the currency is called pula, meaning ''rain''.', 'התכלת בדגל מסמלת מים — הגשם יקר כל כך עד שהמטבע נקרא ''פולה'', כלומר ''גשם''.'),
  ('BF', 'Burkina Faso', 'בורקינה פאסו', 'hard', 'africa', 'Ouagadougou', 'ואגאדוגו', 'flags/4x3/bf.svg', 'The name Burkina Faso is usually translated as ''land of upright people''.', 'השם בורקינה פאסו מתורגם בדרך כלל כ''ארץ האנשים הישרים''.'),
  ('BI', 'Burundi', 'בורונדי', 'hard', 'africa', 'Gitega', 'גיטגה', 'flags/4x3/bi.svg', 'Burundi moved its political capital from Bujumbura to Gitega in 2019.', 'בורונדי העבירה את בירתה הפוליטית מבוז׳ומבורה לגיטגה ב-2019.'),
  ('CV', 'Cape Verde', 'כף ורדה', 'hard', 'africa', 'Praia', 'פראיה', 'flags/4x3/cv.svg', 'The ten stars on the flag stand for the archipelago''s ten main islands.', 'עשרת הכוכבים בדגל מייצגים את עשרת האיים העיקריים של הארכיפלג.'),
  ('CM', 'Cameroon', 'קמרון', 'medium', 'africa', 'Yaoundé', 'יאונדה', 'flags/4x3/cm.svg', 'Cameroon is often called ''Africa in miniature'' for its varied landscapes.', 'קמרון מכונה לעתים ''אפריקה בזעיר אנפין'' בשל מגוון הנופים שלה.'),
  ('CF', 'Central African Republic', 'הרפובליקה המרכז־אפריקאית', 'hard', 'africa', 'Bangui', 'בנגי', 'flags/4x3/cf.svg', 'The flag combines the colours of the French tricolour with the pan-African colours, joined by a red vertical stripe.', 'הדגל משלב את צבעי הדגל הצרפתי עם הצבעים הפאן־אפריקאיים, ופס אדום אנכי מחבר ביניהם.'),
  ('TD', 'Chad', 'צ׳אד', 'hard', 'africa', 'N''Djamena', 'אנג׳מנה', 'flags/4x3/td.svg', 'Chad''s flag is nearly identical to Romania''s — only the shade of blue differs.', 'דגל צ׳אד כמעט זהה לדגל רומניה — רק גוון הכחול שונה.'),
  ('KM', 'Comoros', 'קומורו', 'hard', 'africa', 'Moroni', 'מורוני', 'flags/4x3/km.svg', 'The four stripes and four stars represent the four main islands, including Mayotte, which France administers.', 'ארבעת הפסים וארבעת הכוכבים מייצגים את ארבעת האיים העיקריים, כולל מאיוט שבשליטת צרפת.'),
  ('CG', 'Republic of the Congo', 'הרפובליקה של קונגו', 'hard', 'africa', 'Brazzaville', 'ברזוויל', 'flags/4x3/cg.svg', 'Brazzaville and Kinshasa face each other across the Congo River — the closest pair of capitals in the world after Rome and Vatican City.', 'ברזוויל וקינשאסה ניצבות זו מול זו משני צדי נהר קונגו — צמד הבירות הקרובות ביותר בעולם אחרי רומא והוותיקן.'),
  ('CD', 'DR Congo', 'הרפובליקה הדמוקרטית של קונגו', 'medium', 'africa', 'Kinshasa', 'קינשאסה', 'flags/4x3/cd.svg', 'DR Congo is the largest country in sub-Saharan Africa by area.', 'הרפובליקה הדמוקרטית של קונגו היא המדינה הגדולה ביותר באפריקה שמדרום לסהרה.'),
  ('CI', 'Côte d''Ivoire', 'חוף השנהב', 'medium', 'africa', 'Yamoussoukro', 'יאמוסוקרו', 'flags/4x3/ci.svg', 'Its flag is a mirror image of Ireland''s, with orange at the hoist.', 'הדגל הוא תמונת ראי של דגל אירלנד — הכתום נמצא בצד התורן.'),
  ('DJ', 'Djibouti', 'ג׳יבוטי', 'hard', 'africa', 'Djibouti', 'ג׳יבוטי', 'flags/4x3/dj.svg', 'Lake Assal in Djibouti is the lowest point in Africa.', 'אגם אסאל בג׳יבוטי הוא הנקודה הנמוכה ביותר ביבשת אפריקה.'),
  ('EG', 'Egypt', 'מצרים', 'easy', 'africa', 'Cairo', 'קהיר', 'flags/4x3/eg.svg', 'The golden eagle in the centre of the flag is the Eagle of Saladin.', 'הנשר הזהוב במרכז הדגל הוא ''נשר צלאח א־דין''.'),
  ('GQ', 'Equatorial Guinea', 'גינאה המשוונית', 'hard', 'africa', 'Malabo', 'מלבו', 'flags/4x3/gq.svg', 'It is the only African country where Spanish is an official language.', 'זו המדינה היחידה באפריקה שספרדית היא שפה רשמית בה.'),
  ('ER', 'Eritrea', 'אריתריאה', 'hard', 'africa', 'Asmara', 'אסמרה', 'flags/4x3/er.svg', 'Eritrea gained independence from Ethiopia in 1993.', 'אריתריאה קיבלה עצמאות מאתיופיה ב-1993.'),
  ('SZ', 'Eswatini', 'אסוואטיני', 'hard', 'africa', 'Mbabane', 'מבבנה', 'flags/4x3/sz.svg', 'Formerly known as Swaziland, the country changed its name to Eswatini in 2018.', 'המדינה, שנודעה בעבר בשם סווזילנד, שינתה את שמה לאסוואטיני ב-2018.'),
  ('ET', 'Ethiopia', 'אתיופיה', 'medium', 'africa', 'Addis Ababa', 'אדיס אבבה', 'flags/4x3/et.svg', 'Ethiopia''s green, yellow and red inspired the colours of many African flags.', 'הירוק, הצהוב והאדום של אתיופיה השפיעו על צבעי דגלים רבים באפריקה.'),
  ('GA', 'Gabon', 'גבון', 'hard', 'africa', 'Libreville', 'ליברוויל', 'flags/4x3/ga.svg', 'The equator runs through Gabon, and dense rainforest covers most of the country.', 'קו המשווה עובר בגבון, ויער גשם צפוף מכסה את רוב שטחה.'),
  ('GM', 'Gambia', 'גמביה', 'hard', 'africa', 'Banjul', 'בנג׳ול', 'flags/4x3/gm.svg', 'The Gambia is the smallest country on mainland Africa and is almost surrounded by Senegal.', 'גמביה היא המדינה הקטנה ביותר ביבשת אפריקה, וכמעט כולה מוקפת בסנגל.'),
  ('GH', 'Ghana', 'גאנה', 'medium', 'africa', 'Accra', 'אקרה', 'flags/4x3/gh.svg', 'The black star on Ghana''s flag gave its national football team its nickname, the Black Stars.', 'הכוכב השחור בדגל העניק לנבחרת הכדורגל את כינויה — ''הכוכבים השחורים''.'),
  ('GN', 'Guinea', 'גינאה', 'hard', 'africa', 'Conakry', 'קונקרי', 'flags/4x3/gn.svg', 'Guinea''s flag uses the same colours as Mali''s, in reverse order.', 'דגל גינאה משתמש באותם צבעים כמו דגל מאלי, בסדר הפוך.'),
  ('GW', 'Guinea-Bissau', 'גינאה ביסאו', 'hard', 'africa', 'Bissau', 'ביסאו', 'flags/4x3/gw.svg', 'The black star on the red band is a symbol of African unity.', 'הכוכב השחור על הפס האדום הוא סמל לאחדות אפריקה.'),
  ('KE', 'Kenya', 'קניה', 'medium', 'africa', 'Nairobi', 'ניירובי', 'flags/4x3/ke.svg', 'A Maasai shield and two crossed spears sit at the centre of the flag.', 'במרכז הדגל מגן מסאי ושתי חניתות מוצלבות.'),
  ('LS', 'Lesotho', 'לסוטו', 'hard', 'africa', 'Maseru', 'מסרו', 'flags/4x3/ls.svg', 'Lesotho is entirely surrounded by South Africa, and all of its land lies above 1,000 metres.', 'לסוטו מוקפת כולה בדרום אפריקה, וכל שטחה נמצא בגובה של יותר מ-1,000 מטר.'),
  ('LR', 'Liberia', 'ליבריה', 'hard', 'africa', 'Monrovia', 'מונרוביה', 'flags/4x3/lr.svg', 'Liberia''s flag is modelled on the US flag; its eleven stripes represent the signatories of its declaration of independence.', 'דגל ליבריה מבוסס על דגל ארצות הברית; 11 הפסים מייצגים את החותמים על הכרזת העצמאות.'),
  ('LY', 'Libya', 'לוב', 'medium', 'africa', 'Tripoli', 'טריפולי', 'flags/4x3/ly.svg', 'From 1977 to 2011 Libya''s flag was plain green — the only national flag of a single colour.', 'בין 1977 ל-2011 דגל לוב היה ירוק לחלוטין — הדגל הלאומי היחיד בצבע אחד.'),
  ('MG', 'Madagascar', 'מדגסקר', 'medium', 'africa', 'Antananarivo', 'אנטננריבו', 'flags/4x3/mg.svg', 'Madagascar is the fourth-largest island in the world.', 'מדגסקר היא האי הרביעי בגודלו בעולם.'),
  ('MW', 'Malawi', 'מלאווי', 'hard', 'africa', 'Lilongwe', 'לילונגווה', 'flags/4x3/mw.svg', 'The rising sun on the flag represents the dawn of hope and freedom for Africa.', 'השמש העולה בדגל מסמלת את שחר התקווה והחירות לאפריקה.'),
  ('ML', 'Mali', 'מאלי', 'hard', 'africa', 'Bamako', 'במקו', 'flags/4x3/ml.svg', 'Timbuktu, once a great centre of Islamic learning, is in Mali.', 'טימבוקטו, שהייתה מרכז חשוב של לימוד אסלאמי, נמצאת במאלי.'),
  ('MR', 'Mauritania', 'מאוריטניה', 'hard', 'africa', 'Nouakchott', 'נואקשוט', 'flags/4x3/mr.svg', 'In 2017 Mauritania added red stripes to its flag to honour those who fought for independence.', 'ב-2017 נוספו לדגל מאוריטניה פסים אדומים לזכר הלוחמים לעצמאות.'),
  ('MU', 'Mauritius', 'מאוריציוס', 'hard', 'africa', 'Port Louis', 'פורט לואי', 'flags/4x3/mu.svg', 'Mauritius was the only known home of the dodo, extinct since the 17th century.', 'מאוריציוס הייתה בית הגידול היחיד של הדודו, שנכחד במאה ה-17.'),
  ('MA', 'Morocco', 'מרוקו', 'medium', 'africa', 'Rabat', 'רבאט', 'flags/4x3/ma.svg', 'The green five-pointed star on Morocco''s flag is known as the Seal of Solomon.', 'הכוכב הירוק בעל חמשת הקצוות בדגל מרוקו מכונה ''חותם שלמה''.'),
  ('MZ', 'Mozambique', 'מוזמביק', 'medium', 'africa', 'Maputo', 'מפוטו', 'flags/4x3/mz.svg', 'Mozambique''s flag features an AK-47 rifle.', 'בדגל מוזמביק מופיע רובה קלצ׳ניקוב (AK-47).'),
  ('NA', 'Namibia', 'נמיביה', 'hard', 'africa', 'Windhoek', 'וינדהוק', 'flags/4x3/na.svg', 'The Namib Desert, along Namibia''s coast, is considered one of the oldest deserts in the world.', 'מדבר נמיב שלאורך החוף נחשב לאחד המדבריות העתיקים בעולם.'),
  ('NE', 'Niger', 'ניז׳ר', 'hard', 'africa', 'Niamey', 'ניאמיי', 'flags/4x3/ne.svg', 'Niger''s flag resembles India''s, but its orange disc has no spokes.', 'דגל ניז׳ר דומה לדגל הודו, אך בעיגול הכתום שבמרכזו אין חישורים.'),
  ('NG', 'Nigeria', 'ניגריה', 'medium', 'africa', 'Abuja', 'אבוג׳ה', 'flags/4x3/ng.svg', 'Nigeria is the most populous country in Africa.', 'ניגריה היא המדינה המאוכלסת ביותר באפריקה.'),
  ('RW', 'Rwanda', 'רואנדה', 'hard', 'africa', 'Kigali', 'קיגלי', 'flags/4x3/rw.svg', 'Rwanda is known as the ''land of a thousand hills''.', 'רואנדה מכונה ''ארץ אלף הגבעות''.'),
  ('ST', 'São Tomé and Príncipe', 'סאו טומה ופרינסיפה', 'hard', 'africa', 'São Tomé', 'סאו טומה', 'flags/4x3/st.svg', 'It is the second-smallest country in Africa by area, after the Seychelles.', 'זו המדינה השנייה הקטנה ביותר באפריקה בשטחה, אחרי סיישל.'),
  ('SN', 'Senegal', 'סנגל', 'hard', 'africa', 'Dakar', 'דקאר', 'flags/4x3/sn.svg', 'Dakar sits on the westernmost point of mainland Africa.', 'דקאר שוכנת בנקודה המערבית ביותר של יבשת אפריקה.'),
  ('SC', 'Seychelles', 'סיישל', 'hard', 'africa', 'Victoria', 'ויקטוריה', 'flags/4x3/sc.svg', 'Five diagonal bands fan out from the lower hoist corner of the flag.', 'חמישה פסים אלכסוניים נפרשים בדגל מהפינה התחתונה שליד התורן.'),
  ('SL', 'Sierra Leone', 'סיירה לאונה', 'hard', 'africa', 'Freetown', 'פריטאון', 'flags/4x3/sl.svg', 'Sierra Leone''s name comes from the Portuguese for ''lion mountains''.', 'השם סיירה לאונה מגיע מפורטוגזית ופירושו ''הרי האריה''.'),
  ('SO', 'Somalia', 'סומליה', 'medium', 'africa', 'Mogadishu', 'מוגדישו', 'flags/4x3/so.svg', 'The five points of the white star represent the five regions where Somali people live.', 'חמשת קצות הכוכב הלבן מייצגים את חמשת האזורים שבהם חיים סומלים.'),
  ('ZA', 'South Africa', 'דרום אפריקה', 'easy', 'africa', 'Pretoria', 'פרטוריה', 'flags/4x3/za.svg', 'South Africa has three capitals: Pretoria (executive), Cape Town (legislative) and Bloemfontein (judicial).', 'לדרום אפריקה שלוש בירות: פרטוריה (מבצעת), קייפטאון (מחוקקת) ובלומפונטיין (שופטת).'),
  ('SS', 'South Sudan', 'דרום סודן', 'hard', 'africa', 'Juba', 'ג׳ובה', 'flags/4x3/ss.svg', 'South Sudan became independent in 2011, making it the newest UN member state.', 'דרום סודן קיבלה עצמאות ב-2011, והיא המדינה החדשה ביותר החברה באו״ם.'),
  ('SD', 'Sudan', 'סודן', 'hard', 'africa', 'Khartoum', 'חרטום', 'flags/4x3/sd.svg', 'In Khartoum the Blue Nile and the White Nile meet to form the Nile.', 'בחרטום נפגשים הנילוס הכחול והנילוס הלבן ויוצרים את הנילוס.'),
  ('TZ', 'Tanzania', 'טנזניה', 'medium', 'africa', 'Dodoma', 'דודומה', 'flags/4x3/tz.svg', 'Mount Kilimanjaro, Africa''s highest peak, is in Tanzania.', 'הר קילימנג׳רו, הפסגה הגבוהה ביותר באפריקה, נמצא בטנזניה.'),
  ('TG', 'Togo', 'טוגו', 'hard', 'africa', 'Lomé', 'לומה', 'flags/4x3/tg.svg', 'Togo''s flag has five horizontal stripes and a white star on a red square.', 'בדגל טוגו חמישה פסים אופקיים וכוכב לבן על ריבוע אדום.'),
  ('TN', 'Tunisia', 'תוניסיה', 'medium', 'africa', 'Tunis', 'תוניס', 'flags/4x3/tn.svg', 'The ruins of ancient Carthage lie on the outskirts of Tunis.', 'חורבות קרתגו העתיקה שוכנות בפאתי תוניס.'),
  ('UG', 'Uganda', 'אוגנדה', 'medium', 'africa', 'Kampala', 'קמפלה', 'flags/4x3/ug.svg', 'The bird on Uganda''s flag is a grey crowned crane.', 'הציפור בדגל אוגנדה היא עגור מוכתר אפור.'),
  ('ZM', 'Zambia', 'זמביה', 'hard', 'africa', 'Lusaka', 'לוסקה', 'flags/4x3/zm.svg', 'Unusually, the emblem on Zambia''s flag — an orange eagle — sits on the fly side, away from the hoist.', 'באופן חריג, הסמל בדגל זמביה — עיט כתום — ממוקם בצד הרחוק מהתורן.'),
  ('ZW', 'Zimbabwe', 'זימבבואה', 'medium', 'africa', 'Harare', 'הרארה', 'flags/4x3/zw.svg', 'The bird on the flag is the Zimbabwe Bird, a soapstone carving found at Great Zimbabwe.', 'הציפור בדגל היא ''ציפור זימבבואה'', פסל אבן סבון שנמצא באתר זימבבואה הגדולה.'),
  ('AF', 'Afghanistan', 'אפגניסטן', 'medium', 'asia', 'Kabul', 'קאבול', 'flags/4x3/af.svg', 'Afghanistan has no coastline; the narrow Wakhan Corridor gives it a short border with China.', 'לאפגניסטן אין מוצא לים; פרוזדור ואחאן הצר מעניק לה גבול קצר עם סין.'),
  ('AM', 'Armenia', 'ארמניה', 'medium', 'asia', 'Yerevan', 'ירוואן', 'flags/4x3/am.svg', 'Mount Ararat, a national symbol of Armenia, lies across the border in Türkiye.', 'הר אררט, סמל לאומי של ארמניה, נמצא בפועל מעבר לגבול, בטורקיה.'),
  ('AZ', 'Azerbaijan', 'אזרבייג׳ן', 'medium', 'asia', 'Baku', 'באקו', 'flags/4x3/az.svg', 'Baku lies about 28 metres below sea level, making it the lowest-lying national capital.', 'באקו נמצאת כ-28 מטר מתחת לפני הים — הבירה הנמוכה בעולם.'),
  ('BH', 'Bahrain', 'בחריין', 'hard', 'asia', 'Manama', 'מנאמה', 'flags/4x3/bh.svg', 'The five white points on Bahrain''s flag represent the Five Pillars of Islam.', 'חמשת המשולשים הלבנים בדגל בחריין מייצגים את חמשת עמודי האסלאם.'),
  ('BD', 'Bangladesh', 'בנגלדש', 'medium', 'asia', 'Dhaka', 'דאקה', 'flags/4x3/bd.svg', 'The red disc is set slightly towards the hoist so it appears centred when the flag flies.', 'העיגול האדום מוזז מעט לכיוון התורן כדי שייראה ממורכז כשהדגל מתנופף.'),
  ('BT', 'Bhutan', 'בהוטן', 'medium', 'asia', 'Thimphu', 'טימפו', 'flags/4x3/bt.svg', 'The white dragon on the flag is Druk, the Thunder Dragon — Bhutan''s own name for itself is Druk Yul.', 'הדרקון הלבן בדגל הוא ''דרוק'', דרקון הרעם — ובשפה המקומית בהוטן נקראת ''דרוק יול''.'),
  ('BN', 'Brunei', 'ברוניי', 'hard', 'asia', 'Bandar Seri Begawan', 'בנדר סרי בגוואן', 'flags/4x3/bn.svg', 'Brunei shares the island of Borneo with Malaysia and Indonesia.', 'ברוניי חולקת את האי בורנאו עם מלזיה ואינדונזיה.'),
  ('KH', 'Cambodia', 'קמבודיה', 'medium', 'asia', 'Phnom Penh', 'פנום פן', 'flags/4x3/kh.svg', 'Cambodia''s flag shows Angkor Wat — one of very few national flags to depict a building.', 'בדגל קמבודיה מופיע מקדש אנגקור וואט — אחד הדגלים הלאומיים הבודדים שמופיע בהם מבנה.'),
  ('CN', 'China', 'סין', 'easy', 'asia', 'Beijing', 'בייג׳ינג', 'flags/4x3/cn.svg', 'China spans five geographical time zones but uses a single official one.', 'סין משתרעת על פני חמישה אזורי זמן גאוגרפיים, אך משתמשת באזור זמן רשמי אחד.'),
